// Input generated by analysis/downshifted_search/search.py; native signed spectra.
use anyhow::Result;
use hdf5::File;
use rustplotlib::*;
fn rd(h: &File, k: &str) -> Result<Vec<f64>> { Ok(h.dataset(k)?.read_raw::<f64>()?) }
fn line(f: &mut Figure, p: usize, x: &[f64], y: &[f64], i: usize, name: &str) -> LegendEntry {
    let l=Line::series(x.iter().zip(y).map(|(&x,&y)|[x,y]).collect(),i);
    let key=l.legend(name);f.panels[p].push(Layer::Line(l));key
}
fn main()->Result<()> {
    let h=File::open("data/downshifted_search.h5")?;
    let mut f=ArticleLayout::new(177.,10.)?.figure(1.,85.)?;
    let ps=f.grid(1,3)?;f.height_mm=85.;
    for (p,x) in ps.iter().zip([20.,75.,132.]) { f.panels[*p].rect=Rect::new(x,8.,40.,59.); }
    f.panels[ps[0]].axes=Some(Axes::new([1.,4.2],[117.,118.8],r"$n_e$ ($10^{11}$ m$^{-3}$)","Altitude (km)"));
    f.panels[ps[1]].axes=Some(Axes::new([-0.15,2.5],[117.,118.8],"Line amplitude / noise",""));
    f.panels[ps[2]].axes=Some(Axes::new([5.27,5.41],[-0.15,3.8],"Frequency (MHz)","Excess / noise power"));
    let z=rd(&h,"candidate/density_height_km")?;
    let ne:Vec<_>=rd(&h,"candidate/density_m3")?.iter().map(|x|x/1e11).collect();
    line(&mut f,ps[0],&ne,&z,0,"");
    let row=rd(&h,"candidate/row")?;
    for (p,xmin,xmax) in [(ps[0],1.,4.2),(ps[1],-0.15,2.5)] {
        line(&mut f,p,&[xmin,xmax],&[row[4],row[4]],4,"");
        line(&mut f,p,&[xmin,xmax],&[row[3],row[3]],3,"");
    }
    let mut keys=vec![];
    for (i,name,label) in [(0,"downshifted","Downshifted"),(1,"upshifted","Upshifted")] {
        let amp=rd(&h,&format!("candidate/{name}/amplitude_by_height"))?;
        line(&mut f,ps[1],&amp,&rd(&h,"height_km")?,i,"");
        keys.push(line(&mut f,ps[2],&rd(&h,&format!("candidate/{name}/frequency_mhz"))?,&rd(&h,&format!("candidate/{name}/spectrum"))?,i,label));
    }
    let mut leg=Legend::new(keys);leg.position=LegendPosition::UpperRight;
    f.panels[ps[2]].legend=Some(leg);
    for (p,label) in ps.iter().zip(["(a)","(b)","(c)"]) { f.labels.push(Label::new(label,f.panels[*p].rect.x,3.)); }
    for ext in ["pdf","png"] { f.save(format!("figures/downshifted_search.{ext}"))?; }
    Ok(())
}
